"""Assemble this reviewer's own factual judgment and evidence inventory."""
from pathlib import Path
import hashlib,json,re
ROOT=Path(__file__).resolve().parents[5];HERE=Path(__file__).resolve().parent
REL=str(HERE.relative_to(ROOT))
def sha(path):return hashlib.sha256((ROOT/path).read_bytes()).hexdigest()
def read(name):return json.loads((HERE/name).read_text())
cpu=read('cpu.results.json');extra=read('extra.results.json');hf=read('hf-inventory.results.json')
receipts={r['id']:r for n in ['retrieval.json','retrieval.additional.json','retrieval.final.json'] for r in read(n)}
sources=[];artifacts=[];claims=[]
def artifact(id,name,kind,description,command=None,result=None,environment=None):
 p=REL+'/'+name;a={'id':id,'kind':kind,'path':p,'sha256':sha(p),'description':description}
 if kind=='execution':a.update(command=command,result=result,environment=environment)
 artifacts.append(a)
def original(id,title,receipt_ids,note,kind='official_source',version=None):
 rows=[receipts[r] for r in receipt_ids];primary=rows[0]
 if version is None:
  u=primary['url'];m=re.search(r'/blob/([0-9a-f]{40})|/([0-9a-f]{40})/',u);version=(m.group(1) or m.group(2)) if m else ('arXiv '+u.split('/')[-1] if 'arxiv' in u else 'PyTorch 2.14 reference, accessed 2026-10-04')
 assert all(r.get('status')==200 for r in rows)
 sources.append({'id':id,'kind':kind,'title':title,'url':primary['url'],'version':version,'verified':True,'checked_original':True,'accessed_on':'2026-10-04','authority_reason':'Original authors or maintainers publish this paper, versioned source, or official API definition.','inspection_note':note,'retrievals':[{'url':r['url'],'retrieval_url':r.get('retrieval_url',r.get('final_url',r['url'])),'sha256':r['sha256'],'raw_path':r['path']} for r in rows]})
def code(id,path,note):
 sources.append({'id':id,'kind':'repository_code','title':path,'path':path,'sha256':sha(path),'version':'Current independently read working source; full raw SHA256 is the version boundary','verified':True,'inspection_note':note})
def ev(source,locator,supports):return {'source_id':source,'locator':locator,'supports':supports}
def claim(id,kind,statement,location,evidence,scope,arts=(),verification=None):
 c={'id':id,'kind':kind,'statement':statement,'location':location,'status':'verified','evidence':evidence,'artifact_ids':list(arts),'scope':scope}
 if verification:c['verification']=verification
 claims.append(c)
def verified(expected,observed,details,tolerance=None,denominators=None):
 v={'method':'executed','expected':expected,'observed':observed,'details':details}
 if tolerance:v['tolerance']=tolerance
 if denominators:v['denominators']=denominators
 return v

